#include <stdint.h>
#include <string.h>
#include <endian.h>          // leXX helpers if needed on non‑little endian archs

int main(void) {
    const unsigned char *flash = /* pointer to raw SPI dump */;
    const unsigned char *p = flash;
    if (!p || memcmp(p, "U-Boot", 6) != 0) return 1; // not U-Boot header
    p += 6;
    uint32_t ver = le32toh(*(uint32_t *)p); p +=4;
    uint32_t build= le32toh(*(uint32_t *)p); p +=4;
    printf("Version %u Build %u\n", ver, build);
    const unsigned char *addr = flash + 17; // after magic+ver+build+addr table (16 bytes)
    for (int i=0;i<4;i++) {
        uint32_t addrval=le32toh(*(uint32_t *)(addr+i*4));
        printf("Load addr %u\n", addrval);
    }
    size_t payloadoff=sizeof(magic)+sizeof(version)+sizeof(addr);
    const unsigned char *payload=flash+payloadoff;
    printf("Payload starts at offset %zu\n", payloadoff);
    return 0;
}
